let camera=1.-smoothstep(-.3,1.,dist);
let cameraFill=1.-smoothstep(-2.4,-.9,dist);
let packedHeight=(cueStart-split)*frame.info.y;
let sizeRatio=vec2<f32>(frame.info.x,packedHeight)/vec2<f32>(1.7777778,1.);
let storage=min(sizeRatio.x,sizeRatio.y)*vec2<f32>(1.7777778,1.);
let lens=(size.x/size.y)/1.7777778;
let coord=.5+(q-.5)*min(vec2<f32>(lens,1./lens),vec2<f32>(1.))/max(frame.controls.x,1.);
let sampleUV=vec2<f32>(.5,(cueStart+split)*.5)
    +(clamp(coord,vec2<f32>(.002),vec2<f32>(.998))-.5)*storage/frame.info.xy;
let live=textureSample(input1,linear_sampler,sampleUV);
let shadow=motion*.42*exp(-max(dist,0.)/14.);
let cameraRim=mix(vec3<f32>(.68,.26,.92),vec3<f32>(.90,.61,1.),motion);
let host=vec4<f32>(mix(cameraRim,mix(empty,live.rgb,live.a),cameraFill)*camera,camera);
let beneath=vec4<f32>(panel.rgb*(1.-shadow),panel.a+shadow*(1.-panel.a));
return host+beneath*(1.-host.a);

let t=frame.info.z;let pix=uv*frame.info.xy;
let phase=dot(pix,vec2<f32>(.00085,-.00115))-t*.16;
let crest=.5+.5*cos(6.283185*phase);
let ripple=crest*crest;
let bend=vec2<f32>(sin(pix.y*.008-t*.9),cos(pix.x*.006+t*.8))*4.2*ripple;
let st=(pix+bend+t*vec2<f32>(26.,-12.))/43.;let df=abs(fract(st+.5)-.5)*43.;
let line=1.-smoothstep(.32,1.48,min(df.x,df.y));
let glow=exp(-length((uv-vec2<f32>(-.02,1.04))*vec2<f32>(3.1,3.8))*1.75);
let city=textureSample(input0,linear_sampler,uv).rgb;
let blur=(textureSample(input0,linear_sampler,uv+vec2<f32>(.006,.004)).rgb+textureSample(input0,linear_sampler,uv-vec2<f32>(.006,.004)).rgb)*.5;
var rgb=vec3<f32>(.010,.010,.021)+mix(city,blur,.7)*.44+vec3<f32>(.91,.22,.49)*glow+vec3<f32>(.19,.14,.67)*exp(-length((uv-vec2<f32>(.16,.94))*4.)*1.7);
let highlight=ripple*ripple*ripple;
rgb+=line*(vec3<f32>(.073,.094,.19)+highlight*vec3<f32>(.24,.11,.35));
let feed=textureSample(input1,linear_sampler,uv);
return vec4<f32>(rgb*(1.-feed.a)+feed.rgb,1.);

let cueHeight=min(48.,frame.info.y*.035);
let cueStart=1.-2.*cueHeight/frame.info.y;
let split=round(cueStart*0.61*frame.info.y)/frame.info.y;

let b=textureSample(input0,linear_sampler,uv);
let p=uv-vec2<f32>(.085,.949);
let size=vec2<f32>(.80,.042);
let q=p/size;
let source=vec2<f32>(q.x,cueStart+q.y*(1.-cueStart));
let m=textureSample(input1,linear_sampler,clamp(source,vec2<f32>(0.),vec2<f32>(1.)));
let amount=select(0.,1.,all(q>=vec2<f32>(0.)) && all(q<vec2<f32>(1.)));
return vec4<f32>(b.rgb*(1.-m.a*amount)+m.rgb*amount,1.);

let background = textureSample(input0, linear_sampler, uv);
let glyph = textureSample(input1, linear_sampler, uv);
let phase = fract(uv.x * 1.1 - uv.y * .28 - frame.info.z / 3.2 + .5) - .5;
let shine = exp(-phase * phase * 100.) * .10 + exp(-phase * phase * 2900.) * .12;
return vec4<f32>(mix(background.rgb, vec3<f32>(.82 + shine), glyph.a), 1.);
